public void createDocumentLine(Amount _amount, DimensionDefault _dimension, boolean _groupByDimension)
{
    if (!this.skipCreateDocumentLine())
    {
        // CB201
        if (_groupByDimension || this.getIsGroupByTaxItemGroup())
        {
            this.createLedgerJournalTransInvoice(_amount, _dimension);
        }

        this.createLedgerJournalTrans(_amount, _dimension, _groupByDimension);
    }

    if (this.parmCreateMergedDocumentLine())
    {
        this.createDocumentLineForTotal(_groupByDimension);
    }
}

protected void createLedgerJournalTrans(Amount _amount, DimensionDefault _dimension, boolean _groupByDimension)
{
    TaxGroupJournal taxGroup = ledgerJournalTrans.TaxGroup ? ledgerJournalTrans.TaxGroup : '';
    ledgerJournalTrans.clear();
    ledgerJournalTrans.initValue();

    // CB201
    if (_groupByDimension || this.getIsGroupByTaxItemGroup())
    {
        ledgerJournalTrans.AccountType = rebatePostingAccount.offsetType();
    }
    else
    {
        ledgerJournalTrans.AccountType = rebatePostingAccount.accountType();
    }
    this.setLedgerJournalTransDate(transDate);
    // CB201
    if (_groupByDimension || this.getIsGroupByTaxItemGroup())
    {
        ledgerJournalTrans.Invoice = invoiceId;
        ledgerJournalTrans.Voucher = voucher;
        LedgerJournalTrans.Company = rebatePostingAccount.journalTransOffsetCompanyId();
        ledgerJournalTrans.DefaultDimension = _dimension;

        if (ledgerJournalTrans.AccountType == LedgerJournalACType::Ledger)
        {
            ledgerJournalTrans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(
                ledgerJournalTrans.getLedgerDimensionForLedgerType(rebatePostingAccount.offsetLedgerDimension(), ledgerJournalTrans.Company),
                _dimension);
        }
        else
        {
            ledgerJournalTrans.LedgerDimension = rebatePostingAccount.offsetLedgerDimension();
        }

        ledgerJournalTrans.amountCur2DebCred(rebatePostingAccount.debitCredit() == DebCredProposal::Debit ? -_amount : _amount);

        if (rebateTransactionType == TAMRebateTransactionType::Rebate)
        {
            TaxItemGroup taxItemGroup = this.getTaxItemGroup();
            if (taxItemGroup)
            {
                ledgerJournalTrans.TaxItemGroup = taxItemGroup;
            }

            if (taxGroup)
            {
                ledgerJournalTrans.TaxGroup = taxGroup;
            }
        }
    }
    else
    {
        if (this.shouldGenerateInvoiceId())
        {
            ledgerJournalTrans.Invoice = this.getJournalInvoiceId();
        }

        ledgerJournalTrans.Voucher = this.getVoucher();

        this.initializeLedgerJournalTrans(_amount);
    }

    this.insertLedgerJournalTrans();
}
